ST.xhtml:p:
IF Distance < 0.000001 THEN
  FUN_CalcAxisMoveTime := 0.001;
  RETURN;
END_IF;


dv := Acc * Acc / Jerk;
IF (TargetVel - InitialVel) > dv THEN
  t1 := Acc / Jerk;
  t2 := (TargetVel - InitialVel - dv) / Acc;
ELSE
  t1 := SQRT((TargetVel - InitialVel) / Jerk);
  t2 := 0.0;

END_IF;

s_vm := (TargetVel + InitialVel) * (2.0*t1 + t2);
IF Distance >= s_vm THEN
  t3 := (Distance - s_vm) / TargetVel;
  t_plan := 4.0*t1 + 2.0*t2 + t3;
  FUN_CalcAxisMoveTime := t_plan;
  RETURN;
END_IF;


s_am := 4.0 * InitialVel * Acc / Jerk + 2.0 * Acc * Acc * Acc / Jerk / Jerk;

IF s_am > Distance THEN
  p := 2.0 * InitialVel *Jerk / 3.0;
  q := -Distance*Jerk*Jerk/4.0;
  delta := q * q + p *p*p;
  part1 := -q + SQRT(delta);
  part2 := -q - SQRT(delta);
  IF part1 > 0.0 THEN
    temp := 1.0;
  ELSIF part1 = 0.0 THEN
    temp := 0.0;
  ELSIF part1 < 0.0 THEN
    temp := -1.0;
  END_IF;
  IF part2 > 0.0 THEN
    temp1 := 1.0;
  ELSIF part2 = 0.0 THEN
    temp1 := 0.0;
  ELSIF part2 < 0.0 THEN
    temp1 := -1.0;
  END_IF;
  a1 := temp * EXPT(ABS(part1),1.0 / 3.0) + temp1 *EXPT(ABS(part2),1.0/3.0);
  t_plan := a1;
ELSE
  t1 := Acc / Jerk;
  a := Acc;
  b := 2.0*InitialVel + Jerk * t1*t1 + 2.0*Acc*t1;
  c := s_am - Distance;
  delta := b * b - 4.0*a*c;
  t2 := (-b + SQRT(ABS(delta))) / (2.0*a);
  t_plan := 4.0*t1+2.0*t2;


END_IF;
IF t_plan < 0.001 THEN
  t_plan := 0.001;
END_IF;
FUN_CalcAxisMoveTime := t_plan;
